/* 태생 태그로 시작 도시 고르기 */
function startCityOf(tags) {
  var ids = Object.keys(CITIES);
  for (var i = 0; i < ids.length; i++) {
    var st = CITIES[ids[i]].startTags || [];
    if (st.some(function (t) { return tags && tags[t]; })) return ids[i];
  }
  return START_CITY;
}

/* ───── 기차 ─────
   행동 탭에서 '○○행 기차'를 예약하면 → 다음 차례에 지금 도시의 역(station)에서 사건이 하나 벌어지고
   → 그 사건이 끝나면 운임을 내고 기차에 올라 → 도착 도시의 역에 내린다.
   역 사건 도중 항복해 끌려가면 기차를 놓친다. 운임이 모자라도 못 탄다.
   fare: 3등 운임(원) · slots: 걸리는 시간대 수 (밤을 넘기면 도착해서 바로 잠든다) · line: 노선 */
var TRAINS = [
  { a: 'gyeongseong', b: 'pyongyang', line: '경의선', fare: 3, slots: 1 },
  { a: 'gyeongseong', b: 'busan', line: '경부선', fare: 4, slots: 2 },
  { a: 'pyongyang', b: 'busan', line: '경의선·경부선 직통', fare: 6, slots: 2 }
];
function trainOf(from, to) { return TRAINS.filter(function (t) { return (t.a === from && t.b === to) || (t.a === to && t.b === from); })[0] || null; }
var TRAIN_TEXT = {
  board: ['3등 객차 나무 의자에 몸을 구겨 넣었다. 보따리를 품에 안은 사람들 사이로 기적이 울린다.',
    '석탄 연기를 뒤집어쓰며 객차에 올랐다. 창밖으로 {from}의 지붕들이 멀어진다.',
    '차장이 표에 구멍을 뚫고 지나간다. 맞은편 노인이 삶은 달걀 하나를 건넨다.'],
  arrive: ['{to}역에 내렸다. 낯선 사투리와 짐꾼들의 외침이 한꺼번에 밀려온다.',
    '기차가 {to}역에 멈춰 섰다. 굳은 다리를 펴며 승강장에 내려섰다.',
    '{to}에 닿았다. 승강장 끝에서 순사 하나가 내리는 사람들을 훑어본다.'],
  late: '해가 진 뒤에야 도착했다. 서둘러 셋방부터 찾아야 한다.',
  broke: '표 파는 창구 앞에서 주머니를 뒤졌다. 운임이 모자란다. 떠나는 기차를 바라볼 수밖에 없었다.',
  missed: '기차는 이미 떠나 버렸다.'
};
/* 도시마다 '○○행 기차' 행동을 만든다 */
Object.keys(CITIES).forEach(function (to) {
  PLACES.push({ id: 'train_' + to, kicker: '기차',
    open: function (p) { var cur = (p && p.city) || START_CITY; return !!p && cur !== to && !!trainOf(cur, to); },
    name: function () { return CITIES[to].name + '행 기차'; },
    sub: function (p) {
      var t = trainOf((p && p.city) || START_CITY, to);
      return t.line + ' · 3등 ' + t.fare + '원' + ((p.money || 0) < t.fare ? ' (돈이 모자란다)' : '') + ' · 역에서 일을 한 번 겪고 떠난다';
    },
    next: function (p) { return LOCS[cityDef(p.city).station].name + '에서 ' + CITIES[to].name + '행 기차를 탄다'; },
    loc: function (p) { return cityDef(p && p.city).station; },
    event: function (self, d) { return self.makeTrainDeparture(d, to); } });
});

