QUESTS["gungtaewol"] = {"name": "의병장 궁태월", "start": "qg_start", "startChance": 0.06, "years": [1910, 1919], "loc": "py_market", "followChance": 0.08, "stages": {"met": {"event": "qg_meet", "place": "대성산 산채", "sub": "포수가 산으로 오라는 기별을 보냈다"}, "raid": {"event": "qg_raid", "place": "헌병 분견소 습격", "sub": "의병들이 분견소를 치기로 했다", "chance": 0.7}, "hunted": {"event": "qg_hunt", "place": "토벌대의 포위", "sub": "헌병 토벌대가 대성산을 에워싸고 있다", "chance": 0.9}, "caught": {"event": "qg_prison", "place": "평양 감옥의 의병장", "sub": "궁태월이 붙잡혔다는 소문"}, "success": {"event": "qg_epilogue", "place": "압록강을 건너는 밤", "sub": "의병들이 만주로 떠난다"}, "betray": {"event": "qg_revenge", "place": "", "sub": ""}}};
QUEST_EVENTS["qg_start"] = {"title": "장터의 포수", "kind": "quest", "loc": "py_market", "text": "대동문 장터. 헌병 둘이 상투 튼 사내 하나를 쌀가게 앞에 세워 놓고 몸을 뒤진다. 사내는 산짐승 가죽을 지고 나온 포수 차림인데, 허리춤의 화약 주머니가 불룩하다.\n“이 화약은 뭐냐. 사냥 허가증 내놔.”\n사내가 대답 대신 장터를 둘러본다. 이마에 새 흉터가 있고, 손등에 화승 심지에 덴 자국이 줄줄이 나 있다. 짐승 사냥꾼의 손이 아니다.\n헌병이 포승을 꺼내 든다. 사내의 눈이 당신과 마주친다.", "options": [{"label": "헌병의 눈을 다른 데로 돌린다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "“나리! 저기 소달구지에서 밀주 항아리가 실려 나갑니다!”\n헌병 둘이 고개를 돌리는 순간, 포수가 가죽 짐을 버리고 장꾼들 사이로 사라졌다.\n그날 밤, 셋방 문 앞에 꿩 두 마리와 쪽지가 놓여 있었다. 〈대성산 궁 대장이 뵙고자 함. 박 포수.〉", "fx": {"heat": 1}, "quest": {"id": "gungtaewol", "stage": "met", "wait": 5}}, "ng": {"text": "“밀주? 어디?” 헌병 하나가 돌아보다 당신 얼굴을 뜯어본다.\n“네놈, 저 포수랑 한패지?” 총검이 이쪽을 향한다. 그 틈에 포수가 몸을 빼 달아난다.", "fight": "kenpei", "dist": 2, "questFight": {"id": "gungtaewol", "win": "met", "other": "met", "wait": 5}}}, {"label": "헌병을 덮친다", "ok": {"text": "포승을 든 헌병의 등을 어깨로 들이받았다. 헌병이 쌀가마 위로 고꾸라진다.\n“가시오!” 포수가 한 번 고개를 숙이고 장터 골목으로 내달린다. 남은 헌병이 총검을 겨눈다.", "ambush": true, "fight": "kenpei", "questFight": {"id": "gungtaewol", "win": "met", "other": "met", "wait": 5}}}, {"label": "헌병에게 귀띔한다", "ok": {"text": "헌병에게 다가가 속삭였다. “저 자, 대성산 쪽 산적들과 내통한다는 소문이 있습니다.”\n헌병이 포수를 포승으로 묶으며 당신에게 동전을 던진다. “좋은 정보다. 이름을 적어 두지.”\n끌려가던 포수가 당신을 향해 침을 뱉었다.", "fx": {"money": 5, "heat": -1}, "quest": {"id": "gungtaewol", "stage": "betray", "wait": 7}}}, {"label": "외면한다", "ok": {"text": "고개를 돌렸다. 포수가 끌려가는 소리가 장터의 소음에 묻혔다.\n며칠 뒤, 대동문에 목 없는 시신 하나가 효시됐다는 소문을 들었다.", "quest": {"id": "gungtaewol", "stage": "end_ignored"}}}]};
QUEST_EVENTS["qg_meet"] = {"title": "대성산 산채", "kind": "quest", "loc": "py_home", "text": "박 포수를 따라 밤새 산길을 걸었다. 대성산 깊은 골짜기, 바위 틈에 기대 세운 초막 몇 채. 화톳불 둘레에 서른 남짓한 사내들이 화승총과 낡은 소총을 손질하고 있다.\n초막에서 쉰을 넘긴 사내가 나온다. 구한국 군복 저고리를 아직 걸쳤고, 허리에 군도를 찼다. 의병장 궁태월이다.\n“우리 포수를 살려 줬다지. 고맙소.” 목소리가 낮고 단단하다.\n“정미년에 군대가 해산될 때 나는 총을 내려놓지 않았소. 나라가 없어졌다고 싸움이 끝나는 건 아니오.”\n그가 화톳불 너머를 가리킨다. 쌀자루가 거의 비었다.\n“산 아래 헌병 분견소에 총과 탄약이 쌓였다 하오. 그걸 치려면 분견소 사정을 알아야 하고, 그전에 우리 아이들을 먹여야 하오.\"", "options": [{"label": "분견소를 정탐해 준다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "장꾼으로 꾸미고 분견소 앞을 사흘 동안 오갔다. 보초 교대 시각, 헌병 수, 무기고 자리.\n궁태월이 숯으로 바위에 그린 지도를 보며 고개를 끄덕인다. “열흘 뒤 그믐밤이오. 함께 가겠소?\"", "fx": {"heat": 1}, "quest": {"id": "gungtaewol", "stage": "raid", "wait": 4}}, "ng": {"text": "분견소 앞을 세 번째 지나가는데 보초가 불러 세웠다.\n“네놈, 아까부터 왜 여길 기웃거리나?\"", "fight": "kenpei", "dist": 2, "questFight": {"id": "gungtaewol", "win": "raid", "other": "raid", "wait": 4}}}, {"label": "쌀과 소금을 대 준다", "cost": {"money": 6}, "ok": {"text": "장터에서 쌀 두 말과 소금 한 자루를 사 지게에 지고 산을 올랐다.\n의병들이 화톳불에 밥을 지으며 웃는다. 궁태월이 당신의 어깨를 짚는다. “사람은 배가 불러야 싸우오. 고맙소.\"", "fx": {"heat": 1}, "quest": {"id": "gungtaewol", "stage": "raid", "wait": 4}}}, {"label": "산을 내려간다", "ok": {"text": "“저는… 총을 들 자신이 없소.”\n궁태월이 고개를 끄덕인다. “총 드는 사람만 싸우는 것이 아니오. 오늘 일은 잊으시오. 그대를 위해서요.”\n박 포수가 산 아래까지 길을 안내해 주었다.", "quest": {"id": "gungtaewol", "stage": "end_quit"}}}]};
QUEST_EVENTS["qg_raid"] = {"title": "헌병 분견소 습격", "kind": "quest", "loc": "py_river", "text": "그믐밤. 대동강 상류 마을의 헌병 분견소. 창에 등불 하나가 깜빡인다.\n궁태월이 손짓하자 의병들이 담장 그늘로 흩어진다. 화승총 심지에서 희미한 불빛이 반딧불처럼 떠다닌다.\n“보초는 둘. 무기고는 뒷마당. 총소리가 나면 십 리 밖 헌병대가 말을 타고 온다.” 궁태월이 당신을 본다. “우리는 앞을 친다. 그대는?\"", "options": [{"label": "의병들과 함께 앞장선다", "ok": {"text": "궁태월이 군도를 뽑는다. “가자!”\n의병들이 함성을 지르며 담을 넘는다. 분견소 문이 열리고 헌병들이 총을 들고 뛰어나온다.", "ambush": true, "fight": "kenpei_pair", "questFight": {"id": "gungtaewol", "win": "hunted", "other": "caught", "wait": 0}}}, {"label": "뒷담을 넘어 무기고를 턴다", "check": {"stat": "agi", "diff": "hard"}, "ok": {"text": "앞마당에서 총성이 오가는 사이 뒷담을 넘었다. 무기고 자물쇠를 돌로 내리쳐 부쉈다.\n38식 소총 여덟 자루와 탄약 상자. 의병들이 어깨에 메고 어둠 속으로 사라진다.\n궁태월이 탄약 한 줌을 당신 손에 쥐여 준다. “그대 몫이오.\"", "fx": {"ammo": 8, "heat": 2}, "quest": {"id": "gungtaewol", "stage": "hunted", "wait": 0}}, "ng": {"text": "자물쇠를 부수는 소리에 헌병 하나가 뒷마당으로 뛰어나왔다.\n“무기고다! 막아!\"", "fight": "kenpei", "dist": 2, "questFight": {"id": "gungtaewol", "win": "hunted", "other": "caught", "wait": 0}}}, {"label": "길목에서 망을 본다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "마을 어귀 언덕에 엎드려 헌병대 쪽 길을 지켜보았다. 말발굽 소리가 들리자 부엉이 소리를 세 번 냈다.\n의병들이 빼앗은 총을 메고 산으로 빠져나갔다. 헌병대는 빈 분견소에 도착했다.", "quest": {"id": "gungtaewol", "stage": "hunted", "wait": 0}}, "ng": {"text": "말발굽 소리를 너무 늦게 들었다. 신호를 보내기도 전에 기마헌병들이 마을로 들이닥쳤다.\n의병 여럿이 쓰러지고, 궁태월이 포위당했다.", "fx": {"heat": 2}, "quest": {"id": "gungtaewol", "stage": "caught", "wait": 5}}}]};
QUEST_EVENTS["qg_hunt"] = {"title": "토벌대의 포위", "kind": "quest", "loc": "py_river", "text": "분견소 습격 사흘 뒤. 대성산 아래 마을마다 헌병 토벌대가 들어찼다. 기마헌병들이 산길 입구를 막고, 마을 사람들을 줄 세워 의병 가족을 찾는다.\n박 포수가 산에서 내려와 당신을 찾는다. 얼굴이 피투성이다.\n“산이 다 막혔소. 대장은 아이들을 데리고 북쪽으로 빠져 압록강을 건너겠다 하오. 허나 길을 아는 사람이 없소. 그리고 누군가는 뒤를 막아야 하오.\"", "options": [{"label": "약초꾼 샛길로 의병들을 안내한다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "약초꾼들만 다니는 바위 틈 샛길로 의병들을 이끌었다. 밤새 산등성이 셋을 넘었다.\n새벽, 토벌대의 횃불이 저 아래 골짜기에서 헛되이 맴도는 것이 보였다. 궁태월이 숨을 고르며 웃는다. “그대가 아니었으면 다 죽었소.\"", "fx": {"hp": -2}, "quest": {"id": "gungtaewol", "stage": "success", "wait": 7}}, "ng": {"text": "샛길이 끊겨 있었다. 지난 장마에 바위가 무너진 것이다.\n되돌아 나오는 길목에서 기마헌병의 말 울음소리가 들린다.", "fight": "kibyeong", "dist": 4, "questFight": {"id": "gungtaewol", "win": "success", "other": "caught", "wait": 6}}}, {"label": "뒤에 남아 토벌대를 막는다", "ok": {"text": "바위 뒤에 몸을 붙이고, 의병들이 떠난 길을 등졌다.\n산길 아래에서 헌병들이 올라온다. 궁태월이 떠나며 남긴 말이 귀에 남아 있다. “살아서 다시 봅시다.\"", "ambush": true, "fight": "kenpei_squad", "questFight": {"id": "gungtaewol", "win": "success", "other": "caught", "wait": 6}}}, {"label": "마을에 남아 몸을 숨긴다", "ok": {"text": "산에 오르지 않고 마을 헛간에 숨었다.\n사흘 뒤, 토벌대가 산에서 내려왔다. 포승에 묶인 채 끌려 내려오는 사내들 맨 앞에 궁태월이 있었다.", "quest": {"id": "gungtaewol", "stage": "caught", "wait": 6}}}]};
QUEST_EVENTS["qg_prison"] = {"title": "평양 감옥의 의병장", "kind": "quest", "loc": "py_home", "text": "평양 감옥 붉은 담장 아래. 장터에 방이 붙었다. 〈폭도 수괴 궁태월, 교수형에 처함.〉\n면회실 철망 너머로 궁태월이 끌려 나온다. 다리에 족쇄를 찼고, 군복 저고리는 피에 절었다. 그래도 허리를 꼿꼿이 편다.\n“왔구려.” 그가 웃는다. “내 걱정은 마시오. 나는 정미년에 이미 죽기로 한 사람이오.”\n그가 목소리를 낮춘다. “산에 남은 아이들이 열 남짓 되오. 먹을 것도 없이 숨어 있을 게요.\"", "options": [{"label": "산에 남은 의병들에게 쌀을 보낸다", "cost": {"money": 8}, "ok": {"text": "쌀과 소금을 지게에 지고 대성산에 올랐다. 바위굴에 숨어 있던 의병 열하나가 허겁지겁 밥을 짓는다.\n박 포수가 낡은 탄약 주머니를 건넨다. “대장이 그대한테 주라 했소.\"", "fx": {"ammo": 6, "heat": 1}, "quest": {"id": "gungtaewol", "stage": "end_freed"}}}, {"label": "궁태월의 마지막 말을 받아 적는다", "ok": {"text": "간수가 한눈파는 사이, 궁태월이 불러 주는 대로 소매 안 종이에 적었다. 정미년 이후 함께 싸우다 죽은 의병들의 이름과 고향.\n“이 이름들만은 잊히지 않게 해 주시오.”\n닷새 뒤, 평양 감옥 안에서 형이 집행되었다는 소문이 돌았다.", "fx": {"int": 2, "heat": 1}, "quest": {"id": "gungtaewol", "stage": "end_letter"}}}, {"label": "고개를 숙이고 돌아선다", "ok": {"text": "“송구하오.” 그 말밖에 나오지 않았다.\n궁태월이 고개를 젓는다. “우리 포수를 살려 준 그날, 그대는 이미 의병이었소. 살아남으시오. 그것도 싸움이오.\"", "quest": {"id": "gungtaewol", "stage": "end_prison"}}}]};
QUEST_EVENTS["qg_epilogue"] = {"title": "압록강을 건너는 밤", "kind": "quest", "loc": "py_river", "text": "한겨울 밤, 압록강이 얼었다. 강 건너 만주 쪽 산그늘이 시커멓다.\n얼음 위에 의병 스물 남짓이 줄지어 서 있다. 빼앗은 소총을 메고, 해진 짚신을 새끼줄로 동여맸다.\n궁태월이 당신 앞에 선다. 입김이 하얗다.\n“만주에 가면 독립군 부대에 합류하오. 언젠가는 이 강을 거꾸로 건너오겠지.”\n그가 메고 있던 소총 한 자루를 내린다. “분견소에서 빼앗은 것이오. 그리고, 그대가 청하는 것이 있으면 무엇이든 말하시오.\"", "options": [{"label": "궁태월의 소총을 받는다", "ok": {"text": "38식 보병총이 두 손에 묵직하다. 개머리판에 칼로 새긴 글자. 〈대한〉.\n“쓸 일이 없기를 바라오. 허나 쓸 일이 생기면 망설이지 마시오.\"", "weapon": "rifle", "fx": {"ammo": 6}, "quest": {"id": "gungtaewol", "stage": "end_success"}}}, {"label": "사격을 배운다", "ok": {"text": "떠나기 전 사흘, 박 포수가 산골짜기에서 사격을 가르쳐 주었다. 숨을 참는 법, 바람을 읽는 법.\n“총은 손이 아니라 숨으로 쏘는 것이오.\"", "skill": "aimed", "fx": {"acc": 2, "days": 3}, "quest": {"id": "gungtaewol", "stage": "end_success"}}}, {"label": "돌아올 날을 기다리겠다고 한다", "ok": {"text": "“청할 것은 없소. 돌아오시는 날, 이 강가에서 기다리겠소.”\n궁태월이 말없이 당신 손을 쥔다. 화승 심지에 덴 거친 손이다.\n의병들이 얼음 위를 건너간다. 마지막 그림자가 강 건너 어둠에 묻힐 때까지 지켜보았다.", "fx": {"int": 2, "heat": 1}, "quest": {"id": "gungtaewol", "stage": "end_success"}}}]};
